package com.salespunch360.mobile
import android.app.Application;import androidx.lifecycle.AndroidViewModel;import androidx.lifecycle.viewModelScope;import com.salespunch360.mobile.data.*;import java.io.IOException;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch;import kotlinx.serialization.json.*
data class ProjectState(val loading:Boolean=false,val saving:Boolean=false,val query:String="",val status:String?=null,val rows:List<JsonObject> = emptyList(),val options:JsonObject=buildJsonObject{},val detail:JsonObject?=null,val costing:JsonObject?=null,val editing:JsonObject?=null,val error:String?=null,val budgetEditing:Boolean=false)
class AccountProjectViewModel(app:Application):AndroidViewModel(app){private val api=ApiClient(SecureSession(app));private val _state=MutableStateFlow(ProjectState());val state:StateFlow<ProjectState> = _state;init{load()};fun load()=viewModelScope.launch{_state.value=_state.value.copy(loading=true,error=null);try{val x=api.projects(_state.value.query,_state.value.status);_state.value=_state.value.copy(loading=false,rows=x["rows"]?.jsonArray?.map{it.jsonObject}.orEmpty(),options=api.projectOptions())}catch(e:Exception){fail(e)}};fun search(q:String){_state.value=_state.value.copy(query=q);load()};fun filter(v:String?){_state.value=_state.value.copy(status=v);load()};fun create(){_state.value=_state.value.copy(editing=buildJsonObject{})};fun action(id:String,action:String)=viewModelScope.launch{try{api.projectAction(id,action);open(id);load()}catch(e:Exception){fail(e)}};fun editBudget(v:Boolean=true){_state.value=_state.value.copy(budgetEditing=v)};fun saveBudget(id:String,amount:String)=viewModelScope.launch{try{val x=api.saveProjectBudget(id,buildJsonObject{putJsonArray("lines"){add(buildJsonObject{put("category","GENERAL");put("title","Project budget");put("amount",amount)})}});_state.value=_state.value.copy(detail=x,budgetEditing=false,costing=api.projectCosting(id))}catch(e:Exception){fail(e)}};fun edit(){_state.value=_state.value.copy(editing=_state.value.detail)};fun close(){_state.value=_state.value.copy(editing=null,detail=null,costing=null)};fun open(id:String)=viewModelScope.launch{try{_state.value=_state.value.copy(detail=api.project(id),costing=api.projectCosting(id),options=api.projectOptions(id))}catch(e:Exception){fail(e)}};fun save(p:JsonObject)=viewModelScope.launch{try{val edit=_state.value.editing?.containsKey("id")==true;val x=api.saveProject(edit,p);_state.value=_state.value.copy(editing=null,detail=x,costing=api.projectCosting(x["id"]!!.jsonPrimitive.content));load()}catch(e:Exception){fail(e)}};private fun fail(e:Exception){_state.value=_state.value.copy(loading=false,saving=false,error=if(e is IOException)"Offline. No project change was confirmed." else "Project action rejected by server.")}}
